import { ChangeDetectionStrategy, ChangeDetectorRef, Component } from '@angular/core';
import { SemiFinishedInward, SemiFinishedInwardService } from '../../services/semi-finished-inward-service';
import { Router, RouterLink } from '@angular/router';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-semi-finished-inward',
  imports: [CommonModule, FormsModule, RouterLink],
  templateUrl: './semi-finished-inward.html',
  styleUrl: './semi-finished-inward.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class SemiFinishedInwardComponent {
 Inward: SemiFinishedInward[] = [];
  searchTerm = '';
  constructor(private service: SemiFinishedInwardService, private cd: ChangeDetectorRef, public router: Router) {}

  ngOnInit() {
    this.service.getInwards().subscribe({
      next: (data) => {
        this.Inward = data;
        this.cd.markForCheck();
        console.log("products from backend: ", this.Inward);
      },
      error: (err) => console.error("error fetching inwards: ", err)
    })
  }

FilteredInwards() {
  const term = this.searchTerm.toLowerCase();
  return this.Inward.filter(r =>
    (r.batchNo ?? "").toLowerCase().includes(term) ||
    (r.semiFinished?.name ?? "").toLowerCase().includes(term) ||
    (r.inwardDate ?? "").toLowerCase().includes(term) ||
    (r.bags?.toString() ?? "").includes(term) ||
    (r.grossQty?.toString() ?? "").includes(term)
  );
}
}
